INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Carlos had been training for the city marathon for six months. On race day, he felt nervous at the starting line. Halfway through, he started cramping but kept going slowly. Carlos crossed the finish line exhausted but proud of finishing his first marathon."}'::jsonb, '{"key_points": ["Carlos trained for six months", "he felt nervous at the start", "he cramped but kept going", "he finished his first marathon"]}'::jsonb, 46, 0.55, 'B2', 'approved', 'exam', 'sports', 'a4000000-0000-4000-8000-000000000016', 1),
('passage_reconstruction', '{"passage": "Lena volunteered to organize the neighborhood cleanup event. Only a few people showed up at first, which worried her a little. By midday, word had spread around the neighborhood and many more people joined in. By evening, the whole park looked completely spotless and everyone felt proud."}'::jsonb, '{"key_points": ["Lena organized a neighborhood cleanup", "few people came at first", "word spread and more joined by midday", "the park was spotless by evening"]}'::jsonb, 48, 0.55, 'B2', 'approved', 'exam', 'community', 'a4000000-0000-4000-8000-000000000016', 2);
